CREATE TABLE "SavedSecretResource" ("id" TEXT NOT NULL, "ownerAccountId" TEXT NOT NULL, "displayName" TEXT NOT NULL, "kind" TEXT NOT NULL, "encryptionMode" TEXT NOT NULL, "revision" INTEGER NOT NULL DEFAULT 1, "storedContent" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SavedSecretResource_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SavedSecretAccountGrant" ("resourceId" TEXT NOT NULL, "accountId" TEXT NOT NULL, "createdByAccountId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SavedSecretAccountGrant_pkey" PRIMARY KEY ("resourceId","accountId"));
CREATE TABLE "SavedSecretTeamGrant" ("resourceId" TEXT NOT NULL, "teamId" TEXT NOT NULL, "createdByAccountId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SavedSecretTeamGrant_pkey" PRIMARY KEY ("resourceId","teamId"));
CREATE TABLE "SavedSecretGroupGrant" ("resourceId" TEXT NOT NULL, "teamGroupId" TEXT NOT NULL, "createdByAccountId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SavedSecretGroupGrant_pkey" PRIMARY KEY ("resourceId","teamGroupId"));
CREATE TABLE "SavedSecretResourceKeyEnvelope" ("resourceId" TEXT NOT NULL, "recipientAccountId" TEXT NOT NULL, "encryptedDataKey" BYTEA NOT NULL, "recipientContentPublicKeyFingerprint" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SavedSecretResourceKeyEnvelope_pkey" PRIMARY KEY ("resourceId","recipientAccountId"));
CREATE INDEX "SavedSecretResource_owner_updated_idx" ON "SavedSecretResource"("ownerAccountId","updatedAt");
CREATE INDEX "SavedSecretAccountGrant_accountId_resourceId_idx" ON "SavedSecretAccountGrant"("accountId","resourceId");
CREATE INDEX "SavedSecretTeamGrant_teamId_resourceId_idx" ON "SavedSecretTeamGrant"("teamId","resourceId");
CREATE INDEX "SavedSecretGroupGrant_teamGroupId_resourceId_idx" ON "SavedSecretGroupGrant"("teamGroupId","resourceId");
CREATE INDEX "SavedSecretResourceKeyEnvelope_recipientAccountId_resourceId_idx" ON "SavedSecretResourceKeyEnvelope"("recipientAccountId","resourceId");
